func buildMongoNonNullFieldFilter(field string, sampleDoc bson.M) bson.M {
	if len(sampleDoc) > 0 {
		if v, ok := sampleDoc[field]; ok && v != nil {
			switch v.(type) {
			case string:
				return bson.M{field: bson.M{"$gt": ""}}
			case int, int32, int64, float64:
				return bson.M{field: bson.M{"$type": "number"}}
			case bool:
				return bson.M{field: bson.M{"$type": "bool"}}
			}
		}
	}
	return bson.M{field: bson.M{"$gt": ""}}
}
